// The built-in Rank (PLAYERS order in player-pool.js) is generated by
// scripts/rebuild-rank.js from consensus ADP + last-season production. This
// fails when data changed without a rebuild, and pins the formula's intent.
const assert = require('node:assert/strict');
const { rankKey, rebuild } = require('./scripts/rebuild-rank');

const r = rebuild();
assert.equal(r.next, r.current, 'player-pool.js rank order is stale: run node scripts/rebuild-rank.js and bump DATA_VERSION');

// Formula intent: better last-season production moves a player up, never more
// than 20 picks (0.4 x 50 cap); injured and unlisted players get no edge.
assert.equal(rankKey({ adp: 60, adpF: 60, last: 20, lastTotal: 20 }), 44, 'produced better: moves up 0.4 x gap');
assert.equal(rankKey({ adp: 60, adpF: 60, last: 150, lastTotal: 150 }), 80, 'produced worse: moves down, capped at 20');
assert.equal(rankKey({ adp: 60, adpF: 60, last: 20, lastTotal: 20, inj: { injury: 'x' } }), 60, 'no edge for injured players');
assert.equal(rankKey({ adp: 60, adpF: 60 }), 60, 'no 2025-26 data: consensus');

// Sanity on the shipped order: no player sits 40+ spots from his consensus position.
const byCons = r.ordered.slice().sort((a, b) => require('./draft-core').marketRank(a) - require('./draft-core').marketRank(b));
const consPos = new Map(byCons.map((p, i) => [p.n, i + 1]));
const far = r.ordered.filter((p, i) => Math.abs(i + 1 - consPos.get(p.n)) >= 40).map(p => p.n);
assert(far.length <= 5, 'built-in rank drifted far from consensus: ' + far.join(', '));

console.log('rank order tests passed; ' + r.ordered.length + ' players, ' + far.length + ' 40+ from consensus order');
